{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Clinical absolute bioavailability was only 4% (range 1-9%) in humans, well below the 20% threshold, supporting a low-F outcome for a polar, high-MW drug-like molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Gemcitabine, a polar nucleoside analog, has human oral bioavailability of only 10%, directly demonstrating that polar nucleoside-like molecules with many H-bonding groups are poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Levovirin, a highly polar nucleoside, has ~10% human oral bioavailability due to very low permeability, analogous to the query's multiple polar and ionizable groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "R1479, a ribonucleoside analog, had absolute oral bioavailability of 6-18% in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "ATP, a phosphate-containing nucleotide, had estimated oral bioavailability of only 3.2% from distal-release pellets, supporting very low absorption for phosphate-bearing molecules like the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Didanosine, a small nucleoside, reached 40-50% absolute oral bioavailability in adults at a 200 mg dose, providing a counterexample that some small nucleosides can exceed 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, highly polar corrinoid-like molecule containing a phosphate diester, ribose, dimethylbenzimidazole, and multiple amide groups. High-transfer experimental evidence from polar nucleoside/nucleotide analogs consistently shows low oral bioavailability (4-19%), and the only high-F example (didanosine) is a much smaller nucleoside whose absorption behavior does not transfer to this macrocycle. Therefore the query is predicted to have F < 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for a corrinoid/cobalamin-like molecule is available; potential active absorption via intrinsic factor or other transporters is not captured by the nucleoside analog evidence.",
    "Didanosine shows dose-dependent oral bioavailability, so nucleoside absorption can be variable; however, the query's much larger size and polar phosphate/amide content make high passive absorption unlikely."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

